package dev.zomboid.turretpower;
import java.util.*;import dev.zomboid.survival.*;import com.entropy.tacz_turrets.turret.TurretEntity;
public class Checks {
 static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 public record P(int x,int y,int z){public double distSqr(P p){return (x-p.x)*(x-p.x)+(y-p.y)*(y-p.y)+(z-p.z)*(z-p.z);}public P offset(int a,int b,int c){return new P(x+a,y+b,z+c);}}
 public static class S {public String id;public S(String id){this.id=id;}public String getBlock(){return id;}public boolean is(Object tag){return id.contains("glass");}}
 public static class W {public long time;public boolean client,loaded=true,bedWorks=true;public Map<P,MachineEntity> machines=new HashMap<>();public Map<P,S> blocks=new HashMap<>();public List<Object> mobs=new ArrayList<>(),players=new ArrayList<>();public List<Object> sounds=new ArrayList<>();public boolean isClientSide(){return client;}public long getGameTime(){return time;}public boolean hasChunkAt(P p){return loaded;}public Object getBlockEntity(P p){return machines.get(p);}public S getBlockState(P p){return blocks.getOrDefault(p,new S("minecraft:air"));}public List<Object> getEntitiesOfClass(Class<?> c,Object box){return mobs;}public List<Object> players(){return players;}public W dimensionType(){return this;}public boolean bedWorks(){return bedWorks;}public void playSound(Object player,P pos,Object sound,Object channel,float volume,float pitch){sounds.add(sound);}}
 public static class Box {public Object inflate(double d){return this;}}
 public static class T {public final W w;public Object target;public double distance=16;public boolean visible=true,alive=true,enabled=true,gun=true,ammo=true;public int invulnerableTime;public T(W w){this.w=w;}public W level(){return w;}public P blockPosition(){return new P(0,0,0);}public boolean hasLineOfSight(Object t){return visible;}public T getSensing(){return this;}public boolean isAlive(){return alive;}public boolean isValidTarget(Object t){return enabled&&distance<=400;}public double distanceToSqr(Object t){return distance;}public Object getTarget(){return target;}public boolean isEnabled(){return enabled;}public boolean hasGun(){return gun;}public boolean gunHasAmmo(){return ammo;}public Object getUUID(){return this;}public Box getBoundingBox(){return new Box();}}
 public static class Mob extends T {public String kind="minecraft:zombie";public int hits;public Mob(W w){super(w);}public String getType(){return kind;}public void setTarget(Object t){target=t;}public void doHurtTarget(Object t){hits++;}}
 public static class Fire {public Object shooter;public boolean canceled;Fire(Object t){shooter=t;}public Object getShooter(){return shooter;}public boolean isCanceled(){return canceled;}public void setCanceled(boolean b){canceled=b;}}
 public static class Register {public Map<Object,Object> entries=new HashMap<>();public Object getRegistryKey(){return net.minecraft.core.registries.Registries.SOUND_EVENT;}public void register(Object key,Object id,java.util.function.Supplier<?> supplier){entries.put(id,supplier.get());}}
 public static void main(String[] args){W w=new W();TurretEntity t=new TurretEntity(w);T target=new T(w);t.target=target;P p=new P(25,0,0);MachineEntity g=new MachineEntity();w.machines.put(p,g);w.blocks.put(p,new S("doomsday_decoration:generator"));MachineEntity.GENERATORS.put(w,new HashSet<>(Set.of(p)));
  ok(Link.power(t),"generator exactly 25 blocks");ok(Link.allowed(t),"powered visible close target");ok(g.energy.stored==10000,"checks do not consume");
  w.client=true;ok(!Link.allowed(t)&&!Link.power(t),"client cannot fire");Fire visual=new Fire(t);Link.fire(visual);ok(!visual.canceled&&g.energy.stored==10000,"client visuals untouched");w.client=false;
  w.loaded=false;ok(!Link.power(t),"unloaded generator");w.loaded=true;
  w.blocks.put(p,new S("other:generator"));ok(!Link.power(t),"other mod energy rejected");w.blocks.put(p,new S("doomsday_decoration:generator"));
  g.energy.stored=99;ok(!Link.allowed(t),"100 FE required");g.energy.stored=10000;
  t.distance=400;ok(Link.allowed(t),"20 blocks inclusive");t.distance=400.01;ok(!Link.allowed(t),"beyond 20 rejected");t.distance=16;
  t.visible=false;Fire blocked=new Fire(t);Link.fire(blocked);ok(blocked.canceled&&g.energy.stored==10000,"wall cancels before ammo and energy");t.visible=true;
  t.ammo=false;Fire empty=new Fire(t);Link.fire(empty);ok(empty.canceled&&g.energy.stored==10000,"empty gun no power drain");t.ammo=true;
  Fire first=new Fire(t);Link.fire(first);ok(!first.canceled&&g.energy.stored==9900,"first real round consumes 100 FE");Fire duplicate=new Fire(t);Link.fire(duplicate);ok(duplicate.canceled&&g.energy.stored==9900,"same tick duplicate suppressed");
  w.time=2;Link.fire(new Fire(t));w.time=4;Link.fire(new Fire(t));ok(g.energy.stored==9700,"three-round burst costs 300 FE");w.time=15;ok(!Link.allowed(t),"burst pause enforced");w.time=16;ok(Link.allowed(t),"next burst after twelve ticks");
  // Delayed native burst loses energy/LOS between rounds.
  g.energy.stored=0;Fire noPower=new Fire(t);Link.fire(noPower);ok(noPower.canceled,"scheduled bullet no energy canceled");g.energy.stored=9700;t.visible=false;Fire behindWall=new Fire(t);Link.fire(behindWall);ok(behindWall.canceled&&g.energy.stored==9700,"scheduled bullet new wall canceled");t.visible=true;
  Fire external=new Fire(t);external.canceled=true;Link.fire(external);ok(g.energy.stored==9700,"other mod canceled event untouched");Fire player=new Fire(target);Link.fire(player);ok(!player.canceled&&g.energy.stored==9700,"player fire untouched");
  w.time=60;Link.fire(new Fire(t));ok(Link.burst(t).rounds==1,"long interruption starts fresh burst");
  w.machines.clear();ok(!Link.power(t),"removed generator no retained authorization");w.machines.put(p,g);P far=new P(26,0,0);MachineEntity.GENERATORS.put(w,Set.of(far));w.machines.put(far,g);w.blocks.put(far,new S("doomsday_decoration:generator"));ok(!Link.power(t),"26 block generator excluded");MachineEntity.GENERATORS.put(w,Set.of(p));
  Register reg=new Register();Sounds.register(reg);ok(reg.entries.size()==2,"both sounds registered");w.time=80;Sounds.tick(t);ok(w.sounds.size()==2,"idle and first target alert");w.time=81;Sounds.tick(t);ok(w.sounds.size()==2,"no repeated alert");w.time=82;t.target=new T(w);Sounds.tick(t);ok(w.sounds.size()==2,"target switches rate-limited");w.time=160;Sounds.tick(t);ok(w.sounds.size()==3,"idle every four seconds");g.energy.stored=0;w.time=240;Sounds.tick(t);ok(w.sounds.size()==3,"silent without energy");g.energy.stored=9700;
  Mob zombie=new Mob(w);Mob mutant=new Mob(w);mutant.kind="mutantszombies:screamer";Mob cow=new Mob(w);cow.kind="minecraft:cow";w.mobs.addAll(List.of(zombie,mutant,cow));w.time=260;Link.tick(t);ok(zombie.target==t&&mutant.target==t&&cow.target==null,"zombies and mutants target turret, animals untouched");zombie.distance=3;mutant.distance=3;w.time=280;Link.tick(t);ok(zombie.hits==1&&mutant.hits==1,"contact attacks");zombie.visible=false;mutant.target=target;w.time=300;Link.tick(t);ok(zombie.hits==1&&mutant.hits==1,"wall blocks contact and existing player target retained");
  for(String name:new String[]{"generator","fixedgenerator","trailergenerator"}){g.name=name;int tier=name.equals("generator")?0:name.equals("fixedgenerator")?1:2;ok(PowerPolicy.capacity(g)==new int[]{128000,512000,768000}[tier],"double storage "+name);ok(PowerPolicy.output(g)==80*(tier+1),"tier output "+name);ok(PowerPolicy.fuel(g,1600)==1600*(tier+1),"tier fuel duration "+name);}
  g.isGenerator=false;g.name="freezer";ok(PowerPolicy.capacity(g)==64000&&PowerPolicy.demand(g)==2,"appliance balance preserved");
  System.out.println("Turret, sounds, power and generator checks: "+checks);
 }
}
